  1→//! Backfill intelligence for incremental models.
  2→//!
  3→//! Provides batch generation, safety-to-batch-size mapping, and DAG-aware
  4→//! range computation for backfill and backbuild operations.
  5→
  6→use std::collections::HashMap;
  7→
  8→use anyhow::{Context, Result};
  9→use chrono::{Duration, NaiveDate};
 10→use smelt_core::{Granularity, IncrementalConfig};
 11→use smelt_optimizer::{analyze_batch_safety, BatchSafety, Frontmatter, ModelInfo};
 12→
 13→use crate::graph::DependencyGraph;
 14→use crate::temporal::compute_incremental_windows;
 15→use crate::transformer::TimeRange;
 16→
 17→/// A computed execution plan for one model during a backfill/backbuild.
 18→#[derive(Debug, Clone)]
 19→pub struct ModelBackfillPlan {
 20→    /// Model name.
 21→    pub model_name: String,
 22→    /// The partition range — what gets written (DELETE/overwrite scope).
 23→    pub partition_range: TimeRange,
 24→    /// The filter range — what gets read (wider, includes context rows).
 25→    pub filter_range: TimeRange,
 26→    /// The batch safety classification for this model.
 27→    pub batch_safety: BatchSafety,
 28→    /// The batches to execute (each is a partition range).
 29→    pub batches: Vec<BackfillBatch>,
 30→    /// Whether this model is incremental (false = full refresh).
 31→    pub is_incremental: bool,
 32→}
 33→
 34→/// A single batch within a backfill — covers a contiguous time range.
 35→#[derive(Debug, Clone)]
 36→pub struct BackfillBatch {
 37→    /// The partition range for this batch (what gets written).
 38→    pub partition_range: TimeRange,
 39→    /// The filter range for this batch (what gets read — wider for context).
 40→    pub filter_range: TimeRange,
 41→}
 42→
 43→/// Options controlling backfill execution.
 44→#[derive(Debug, Clone, Default)]
 45→pub struct BackfillOptions {
 46→    /// Override batch size in days (takes precedence over safety analysis).
 47→    pub batch_size_days: Option<u32>,
 48→    /// Force per-partition execution (one query per granularity period).
 49→    pub per_partition: bool,
 50→}
 51→
 52→/// Compute backfill plans for models in execution order.
 53→///
 54→/// For a regular range run, all models get the same requested range.
 55→/// Each model's batch strategy is determined by its batch safety analysis.
 56→pub fn compute_range_run_plans(
 57→    execution_order: &[String],
 58→    graph: &DependencyGraph,
 59→    config: &crate::config::Config,
 60→    sources: Option<&smelt_core::SourcesConfig>,
 61→    requested_range: &TimeRange,
 62→    options: &BackfillOptions,
 63→) -> Result<Vec<ModelBackfillPlan>> {
 64→    let mut plans = Vec::new();
 65→
 66→    for model_name in execution_order {
 67→        let model = graph.get_model(model_name)?;
 68→        let frontmatter = Frontmatter::parse(&model.content);
 69→
 70→        let inc_config = config
 71→            .get_incremental_with_metadata(model_name, model.metadata.as_ref().map(|b| b.as_ref()))
 72→            .cloned()
 73→            .or_else(|| frontmatter.as_ref().and_then(|f| f.incremental.clone()));
 74→
 75→        let plan = match inc_config {
 76→            Some(ref inc) => compute_model_backfill_plan(
 77→                model_name,
 78→                &model.content,
 79→                inc,
 80→                sources,
 81→                model.metadata.as_ref().map(|b| b.as_ref()),
 82→                requested_range,
 83→                options,
 84→            )?,
 85→            None => ModelBackfillPlan {
 86→                model_name: model_name.clone(),
 87→                partition_range: requested_range.clone(),
 88→                filter_range: requested_range.clone(),
 89→                batch_safety: BatchSafety::FullyBatchSafe,
 90→                batches: vec![],
 91→                is_incremental: false,
 92→            },
 93→        };
 94→
 95→        plans.push(plan);
 96→    }
 97→
 98→    Ok(plans)
 99→}
100→
101→/// Compute backfill plans for a backbuild operation.
102→///
103→/// Walks the DAG backwards from the target model, expanding ranges
104→/// based on each model's temporal dependencies and data latency.
105→pub fn compute_backbuild_plans(
106→    target_model: &str,
107→    execution_order: &[String],
108→    graph: &DependencyGraph,
109→    config: &crate::config::Config,
110→    sources: Option<&smelt_core::SourcesConfig>,
111→    requested_range: &TimeRange,
112→    options: &BackfillOptions,
113→) -> Result<Vec<ModelBackfillPlan>> {
114→    // Build model ranges: start with the target's requested range,
115→    // then expand upstream ranges based on temporal dependencies.
116→    let mut model_ranges: HashMap<String, TimeRange> = HashMap::new();
117→    model_ranges.insert(target_model.to_string(), requested_range.clone());
118→
119→    // Process in reverse execution order (downstream to upstream)
120→    let reversed: Vec<_> = execution_order.iter().rev().collect();
121→
122→    for model_name in &reversed {
123→        let range = match model_ranges.get(model_name.as_str()) {
124→            Some(r) => r.clone(),
125→            None => continue,
126→        };
127→
128→        let model = graph.get_model(model_name)?;
129→        let frontmatter = Frontmatter::parse(&model.content);
130→
131→        let inc_config = config
132→            .get_incremental_with_metadata(model_name, model.metadata.as_ref().map(|b| b.as_ref()))
133→            .cloned()
134→            .or_else(|| frontmatter.as_ref().and_then(|f| f.incremental.clone()));
135→
136→        if let Some(ref inc) = inc_config {
137→            // Compute the effective window for this model
138→            let model_latency = model
139→                .metadata
140→                .as_ref()
141→                .and_then(|m| m.columns.get(&inc.event_time_column))
142→                .and_then(|c| c.data_latency.as_ref());
143→
144→            let windows =
145→                compute_incremental_windows(&model.content, inc, sources, model_latency, &range);
146→
147→            // Each upstream must provide data for this model's filter range
148→            let upstream_range = &windows.filter_range;
149→
150→            for upstream_name in graph.get_upstream(model_name) {
151→                let existing = model_ranges.get(&upstream_name);
152→                let expanded = match existing {
153→                    Some(existing_range) => union_ranges(existing_range, upstream_range)?,
154→                    None => upstream_range.clone(),
155→                };
156→                model_ranges.insert(upstream_name, expanded);
157→            }
158→        } else {
159→            // Non-incremental: upstreams still need to be included
160→            // (they'll get full refresh), use the same range for any
161→            // upstream that is incremental
162→            for upstream_name in graph.get_upstream(model_name) {
163→                model_ranges.entry(upstream_name).or_insert(range.clone());
164→            }
165→        }
166→    }
167→
168→    // Now compute backfill plans for each model in execution order
169→    let mut plans = Vec::new();
170→
171→    for model_name in execution_order {
172→        let range = match model_ranges.get(model_name.as_str()) {
173→            Some(r) => r,
174→            None => continue,
175→        };
176→
177→        let model = graph.get_model(model_name)?;
178→        let frontmatter = Frontmatter::parse(&model.content);
179→
180→        let inc_config = config
181→            .get_incremental_with_metadata(model_name, model.metadata.as_ref().map(|b| b.as_ref()))
182→            .cloned()
183→            .or_else(|| frontmatter.as_ref().and_then(|f| f.incremental.clone()));
184→
185→        let plan = match inc_config {
186→            Some(ref inc) => compute_model_backfill_plan(
187→                model_name,
188→                &model.content,
189→                inc,
190→                sources,
191→                model.metadata.as_ref().map(|b| b.as_ref()),
192→                range,
193→                options,
194→            )?,
195→            None => ModelBackfillPlan {
196→                model_name: model_name.clone(),
197→                partition_range: range.clone(),
198→                filter_range: range.clone(),
199→                batch_safety: BatchSafety::FullyBatchSafe,
200→                batches: vec![],
201→                is_incremental: false,
202→            },
203→        };
204→
205→        plans.push(plan);
206→    }
207→
208→    Ok(plans)
209→}
210→
211→/// Compute the backfill plan for a single model.
212→fn compute_model_backfill_plan(
213→    model_name: &str,
214→    sql: &str,
215→    inc_config: &IncrementalConfig,
216→    sources: Option<&smelt_core::SourcesConfig>,
217→    model_metadata: Option<&crate::metadata::ModelMetadata>,
218→    requested_range: &TimeRange,
219→    options: &BackfillOptions,
220→) -> Result<ModelBackfillPlan> {
221→    // Analyze batch safety
222→    let model_info = ModelInfo {
223→        name: model_name.to_string(),
224→        sql: sql.to_string(),
225→        refs: vec![],
226→        incremental_config: Some(inc_config.clone()),
227→    };
228→    let batch_safety = analyze_batch_safety(&model_info);
229→
230→    // Compute effective window
231→    let model_latency = model_metadata
232→        .and_then(|m| m.columns.get(&inc_config.event_time_column))
233→        .and_then(|c| c.data_latency.as_ref());
234→    let windows =
235→        compute_incremental_windows(sql, inc_config, sources, model_latency, requested_range);
236→
237→    // Determine batch strategy
238→    let batches = generate_batches(
239→        requested_range,
240→        &windows.filter_range,
241→        &batch_safety,
242→        &inc_config.granularity,
243→        options,
244→    )?;
245→
246→    Ok(ModelBackfillPlan {
247→        model_name: model_name.to_string(),
248→        partition_range: windows.partition_range,
249→        filter_range: windows.filter_range,
250→        batch_safety,
251→        batches,
252→        is_incremental: true,
253→    })
254→}
