256→/// Compute batch safety and generate batches for a single model.
257→///
258→/// This is the per-model API used by the `run` command when a time range is provided.
259→/// It computes batch safety from the SQL, then generates batches accordingly.
260→pub fn compute_batches_for_model(
261→    sql: &str,
262→    inc_config: &IncrementalConfig,
263→    requested_range: &TimeRange,
264→    filter_range: &TimeRange,
265→    options: &BackfillOptions,
266→) -> Result<(BatchSafety, Vec<BackfillBatch>)> {
267→    let model_info = ModelInfo {
268→        name: String::new(),
269→        sql: sql.to_string(),
270→        refs: vec![],
271→        incremental_config: Some(inc_config.clone()),
272→    };
273→    let batch_safety = analyze_batch_safety(&model_info);
274→
275→    let batches = generate_batches(
276→        requested_range,
277→        filter_range,
278→        &batch_safety,
279→        &inc_config.granularity,
280→        options,
281→    )?;
282→
283→    Ok((batch_safety, batches))
284→}
285→
286→/// Generate batches for a backfill based on batch safety and options.
287→fn generate_batches(
288→    requested_range: &TimeRange,
289→    _filter_range: &TimeRange,
290→    batch_safety: &BatchSafety,
291→    granularity: &Granularity,
292→    options: &BackfillOptions,
293→) -> Result<Vec<BackfillBatch>> {
294→    let start = parse_date(&requested_range.start)?;
295→    let end = parse_date(&requested_range.end)?;
296→
297→    if start >= end {
298→        return Ok(vec![]);
299→    }
300→
301→    // Determine batch size in days
302→    let (batch_days, context_days) = if options.per_partition {
303→        // Force per-partition: one granularity period per batch
304→        let period = granularity_days(granularity);
305→        let context = match batch_safety {
306→            BatchSafety::BoundedSafe { context_days, .. } => *context_days,
307→            _ => 0,
308→        };
309→        (period, context)
310→    } else if let Some(override_days) = options.batch_size_days {
311→        let context = match batch_safety {
312→            BatchSafety::BoundedSafe { context_days, .. } => *context_days,
313→            _ => 0,
314→        };
315→        (override_days, context)
316→    } else {
317→        match batch_safety {
318→            BatchSafety::FullyBatchSafe => {
319→                // Single batch for entire range
320→                let total_days = (end - start).num_days() as u32;
321→                (total_days, 0)
322→            }
323→            BatchSafety::BoundedSafe {
324→                max_chunk_days,
325→                context_days,
326→                ..
327→            } => (*max_chunk_days, *context_days),
328→            BatchSafety::PerPartitionOnly { .. } => {
329→                let period = granularity_days(granularity);
330→                let context = 0; // per-partition doesn't need context across partitions
331→                (period, context)
332→            }
333→        }
334→    };
335→
336→    // Generate batch ranges
337→    let mut batches = Vec::new();
338→    let mut batch_start = start;
339→
340→    while batch_start < end {
341→        let batch_end = (batch_start + Duration::days(batch_days as i64)).min(end);
342→
343→        let filter_start = batch_start - Duration::days(context_days as i64);
344→        let filter_end = batch_end;
345→
346→        batches.push(BackfillBatch {
347→            partition_range: TimeRange {
348→                start: batch_start.format("%Y-%m-%d").to_string(),
349→                end: batch_end.format("%Y-%m-%d").to_string(),
350→            },
351→            filter_range: TimeRange {
352→                start: filter_start.format("%Y-%m-%d").to_string(),
353→                end: filter_end.format("%Y-%m-%d").to_string(),
354→            },
355→        });
356→
357→        batch_start = batch_end;
358→    }
359→
360→    Ok(batches)
361→}
362→
363→/// Union two time ranges (take the min start and max end).
364→fn union_ranges(a: &TimeRange, b: &TimeRange) -> Result<TimeRange> {
365→    let a_start = parse_date(&a.start)?;
366→    let b_start = parse_date(&b.start)?;
367→    let a_end = parse_date(&a.end)?;
368→    let b_end = parse_date(&b.end)?;
369→
370→    Ok(TimeRange {
371→        start: a_start.min(b_start).format("%Y-%m-%d").to_string(),
372→        end: a_end.max(b_end).format("%Y-%m-%d").to_string(),
373→    })
374→}
375→
376→fn parse_date(s: &str) -> Result<NaiveDate> {
377→    NaiveDate::parse_from_str(s, "%Y-%m-%d").with_context(|| format!("Invalid date format: {}", s))
378→}
379→
380→fn granularity_days(g: &Granularity) -> u32 {
381→    match g {
382→        Granularity::Hour => 1,
383→        Granularity::Day => 1,
384→        Granularity::Week { .. } => 7,
385→        Granularity::Month => 30,
386→        Granularity::Quarter => 91,
387→        Granularity::Year => 365,
388→    }
389→}
390→
391→/// Format a backfill plan for dry-run display.
392→pub fn format_plan_summary(plans: &[ModelBackfillPlan]) -> String {
393→    let mut lines = Vec::new();
394→
395→    for plan in plans {
396→        if !plan.is_incremental {
397→            lines.push(format!("  {} → full refresh", plan.model_name));
398→            continue;
399→        }
400→
401→        let safety_label = match &plan.batch_safety {
402→            BatchSafety::FullyBatchSafe => "batch-safe".to_string(),
403→            BatchSafety::BoundedSafe {
404→                max_chunk_days,
405→                context_days,
406→                ..
407→            } => {
408→                format!(
409→                    "bounded ({}d chunks, {}d context)",
410→                    max_chunk_days, context_days
411→                )
412→            }
413→            BatchSafety::PerPartitionOnly { .. } => "per-partition".to_string(),
414→        };
415→
416→        lines.push(format!(
417→            "  {} → {} batch(es), range [{}, {}), safety: {}",
418→            plan.model_name,
419→            plan.batches.len(),
420→            plan.partition_range.start,
421→            plan.partition_range.end,
422→            safety_label,
423→        ));
424→
425→        if plan.filter_range.start != plan.partition_range.start
426→            || plan.filter_range.end != plan.partition_range.end
427→        {
428→            lines.push(format!(
429→                "    filter range: [{}, {}) (expanded for temporal context)",
430→                plan.filter_range.start, plan.filter_range.end,
431→            ));
432→        }
433→    }
434→
435→    lines.join("\n")
436→}
