442→    #[test]
443→    fn test_generate_batches_fully_safe() {
444→        let range = TimeRange {
445→            start: "2025-01-01".into(),
446→            end: "2026-01-01".into(),
447→        };
448→        let safety = BatchSafety::FullyBatchSafe;
449→        let options = BackfillOptions::default();
450→
451→        let batches =
452→            generate_batches(&range, &range, &safety, &Granularity::Day, &options).unwrap();
453→
454→        // FullyBatchSafe → single batch for entire range
455→        assert_eq!(batches.len(), 1);
456→        assert_eq!(batches[0].partition_range.start, "2025-01-01");
457→        assert_eq!(batches[0].partition_range.end, "2026-01-01");
458→    }
459→
460→    #[test]
461→    fn test_generate_batches_bounded_safe() {
462→        let range = TimeRange {
463→            start: "2025-01-01".into(),
464→            end: "2025-04-01".into(),
465→        };
466→        let safety = BatchSafety::BoundedSafe {
467→            max_chunk_days: 30,
468→            context_days: 7,
469→            reason: "7-day window lookback".into(),
470→        };
471→        let options = BackfillOptions::default();
472→
473→        let batches =
474→            generate_batches(&range, &range, &safety, &Granularity::Day, &options).unwrap();
475→
476→        // 90 days / 30-day chunks = 3 batches
477→        assert_eq!(batches.len(), 3);
478→
479→        // First batch: partition [Jan 1, Jan 31), filter [Dec 25, Jan 31)
480→        assert_eq!(batches[0].partition_range.start, "2025-01-01");
481→        assert_eq!(batches[0].partition_range.end, "2025-01-31");
482→        assert_eq!(batches[0].filter_range.start, "2024-12-25");
483→
484→        // Last batch: partition [Mar 2, Apr 1)
485→        assert_eq!(batches[2].partition_range.end, "2025-04-01");
486→    }
487→
488→    #[test]
489→    fn test_generate_batches_per_partition() {
490→        let range = TimeRange {
491→            start: "2025-01-01".into(),
492→            end: "2025-01-04".into(),
493→        };
494→        let safety = BatchSafety::FullyBatchSafe;
495→        let options = BackfillOptions {
496→            per_partition: true,
497→            batch_size_days: None,
498→        };
499→
500→        let batches =
501→            generate_batches(&range, &range, &safety, &Granularity::Day, &options).unwrap();
502→
503→        // 3 days → 3 batches (per-partition forced)
504→        assert_eq!(batches.len(), 3);
505→        assert_eq!(batches[0].partition_range.start, "2025-01-01");
506→        assert_eq!(batches[0].partition_range.end, "2025-01-02");
507→        assert_eq!(batches[1].partition_range.start, "2025-01-02");
508→        assert_eq!(batches[1].partition_range.end, "2025-01-03");
509→        assert_eq!(batches[2].partition_range.start, "2025-01-03");
510→        assert_eq!(batches[2].partition_range.end, "2025-01-04");
511→    }
