552→    #[test]
553→    fn test_union_ranges() {
554→        let a = TimeRange {
555→            start: "2025-01-10".into(),
556→            end: "2025-03-01".into(),
557→        };
558→        let b = TimeRange {
559→            start: "2025-01-01".into(),
