  1→use serde::Serialize;
  2→
  3→use crate::analysis::temporal::{analyze_temporal_dependencies, TemporalOffset};
  4→use crate::analysis::{analyze_select, SelectItemKind};
  5→use crate::graph::ModelInfo;
  6→use crate::types::{Opportunity, OpportunityData, Transformation};
  7→
  8→/// Non-deterministic function names that produce different results on each run.
  9→const NONDETERMINISTIC_FUNCTIONS: &[&str] = &[
 10→    "RANDOM",
 11→    "RAND",
 12→    "NOW",
 13→    "CURRENT_TIMESTAMP",
 14→    "CURRENT_DATE",
 15→    "UUID",
 16→    "GEN_RANDOM_UUID",
 17→    "SETSEED",
 18→];
 19→
 20→/// How safely a model can be backfilled in large batches.
 21→///
 22→/// Derived from temporal dependency analysis (Phase 3). Models with no
 23→/// cross-partition dependencies can process any range in a single query;
 24→/// models with bounded lookback need chunked execution; models with
 25→/// unbounded dependencies must go per-partition or full refresh.
 26→#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
 27→pub enum BatchSafety {
 28→    /// Single query for any range — aggregations are partition-local.
 29→    FullyBatchSafe,
 30→    /// Safe for bounded chunks — window functions or joins need context rows
 31→    /// but the dependency is bounded.
 32→    BoundedSafe {
 33→        /// Maximum recommended chunk size in days. Each chunk query fetches
 34→        /// `[start - context_days, end)` but only writes `[start, end)`.
 35→        max_chunk_days: u32,
 36→        /// Extra context days needed before each chunk's start.
 37→        context_days: u32,
 38→        /// Human-readable explanation of why chunking is needed.
 39→        reason: String,
 40→    },
 41→    /// Must process per-partition — cross-partition dependencies are unbounded.
 42→    PerPartitionOnly {
 43→        /// Human-readable explanation of why per-partition is required.
 44→        reason: String,
 45→    },
 46→}
 47→
 48→/// Analyze how safely a model can be backfilled in batches.
 49→///
 50→/// Uses the SQL's temporal dependency (lookback/lookahead) to determine
 51→/// whether a single query can cover any range, or whether the range must
 52→/// be split into chunks or individual partitions.
 53→pub fn analyze_batch_safety(model: &ModelInfo) -> BatchSafety {
 54→    let sql = crate::types::Frontmatter::strip(&model.sql);
 55→    let temporal = analyze_temporal_dependencies(sql);
 56→
 57→    // Determine granularity period for converting Periods→Days
 58→    let period_days = model
 59→        .incremental_config
 60→        .as_ref()
 61→        .map(|c| crate::analysis::temporal::granularity_period_days(&c.granularity))
 62→        .unwrap_or(1);
 63→
 64→    // Check lookback
 65→    let lookback_days = match &temporal.lookback {
 66→        TemporalOffset::Zero => 0,
 67→        TemporalOffset::Periods(n) => n * period_days,
 68→        TemporalOffset::Days(n) => *n,
 69→        TemporalOffset::Unbounded { reason } => {
 70→            return BatchSafety::PerPartitionOnly {
 71→                reason: format!("unbounded lookback: {}", reason),
 72→            };
 73→        }
 74→    };
 75→
 76→    // Check lookahead
 77→    let lookahead_days = match &temporal.lookahead {
 78→        TemporalOffset::Zero => 0,
 79→        TemporalOffset::Periods(n) => n * period_days,
 80→        TemporalOffset::Days(n) => *n,
 81→        TemporalOffset::Unbounded { reason } => {
 82→            return BatchSafety::PerPartitionOnly {
 83→                reason: format!("unbounded lookahead: {}", reason),
 84→            };
 85→        }
 86→    };
 87→
 88→    let context_days = lookback_days.max(lookahead_days);
 89→
 90→    if context_days == 0 {
 91→        BatchSafety::FullyBatchSafe
 92→    } else {
 93→        // Recommend chunks at least 3x the context to keep overhead reasonable.
 94→        // Minimum chunk = 7 days, maximum recommended = 90 days.
 95→        let min_chunk = context_days * 3;
 96→        let max_chunk_days = min_chunk.clamp(7, 90);
 97→
 98→        let reasons: Vec<String> = temporal
 99→            .sources
100→            .iter()
101→            .map(|s| format!("{:?}", s))
102→            .collect();
103→
104→        BatchSafety::BoundedSafe {
105→            max_chunk_days,
106→            context_days,
107→            reason: if reasons.is_empty() {
108→                format!("temporal dependency of {} day(s)", context_days)
109→            } else {
110→                format!(
111→                    "temporal dependency of {} day(s) from: {}",
112→                    context_days,
113→                    reasons.join(", ")
114→                )
115→            },
116→        }
117→    }
118→}
