120→/// Detect incremental materialization opportunity from frontmatter config.
121→pub fn detect(model: &ModelInfo) -> Result<Option<Opportunity>, String> {
122→    let inc_config = match &model.incremental_config {
123→        Some(c) => c,
124→        None => return Ok(None),
125→    };
126→
127→    let analysis = analyze_select(&model.sql).ok_or_else(|| {
128→        format!(
129→            "Model '{}': has incremental config but SQL could not be parsed",
130→            model.name
131→        )
132→    })?;
133→
134→    let partition_col = &inc_config.partition_column;
135→    let event_time_column = &inc_config.event_time_column;
136→    let overrides = &inc_config.safety_overrides;
137→
138→    // Validate partition_column alias exists in SELECT list
139→    let partition_item = analysis.items.iter().find(|item| match item {
140→        SelectItemKind::GroupByKey { alias, .. } => alias == partition_col,
141→        SelectItemKind::CountDistinct { alias, .. } => alias == partition_col,
142→        SelectItemKind::OtherAggregate { alias, .. } => alias == partition_col,
143→    });
144→
145→    let partition_item = partition_item.ok_or_else(|| {
146→        format!(
147→            "Model '{}': incremental partition_column '{}' not found as alias in SELECT list",
148→            model.name, partition_col
149→        )
150→    })?;
151→
152→    // Get the expression for the partition column
153→    let partition_expr = match partition_item {
154→        SelectItemKind::GroupByKey { text, .. } => text.clone(),
155→        SelectItemKind::CountDistinct { argument, .. } => argument.clone(),
156→        SelectItemKind::OtherAggregate { text, .. } => text.clone(),
157→    };
158→
159→    // Validate it appears in GROUP BY
160→    let in_group_by = analysis
161→        .group_by_exprs
162→        .iter()
163→        .any(|expr| expr == &partition_expr);
164→    if !in_group_by {
165→        return Err(format!(
166→            "Model '{}': partition_column '{}' (expression: {}) not found in GROUP BY clause",
167→            model.name, partition_col, partition_expr
168→        ));
169→    }
170→
171→    // Validate event_time_column is referenced in the SQL
172→    let stripped_sql = crate::types::Frontmatter::strip(&model.sql);
173→    if !stripped_sql.contains(event_time_column.as_str()) {
174→        return Err(format!(
175→            "Model '{}': event_time_column '{}' not found in SQL",
176→            model.name, event_time_column
177→        ));
178→    }
179→
180→    // Validate unique_key columns exist in SELECT list (needed for MERGE strategy)
181→    let select_aliases: Vec<&str> = analysis
182→        .items
183→        .iter()
184→        .map(|item| match item {
185→            SelectItemKind::GroupByKey { alias, .. } => alias.as_str(),
186→            SelectItemKind::CountDistinct { alias, .. } => alias.as_str(),
187→            SelectItemKind::OtherAggregate { alias, .. } => alias.as_str(),
188→        })
189→        .collect();
190→
191→    for key_col in &inc_config.unique_key {
192→        if !select_aliases.contains(&key_col.as_str()) {
193→            return Err(format!(
194→                "Model '{}': unique_key column '{}' not found as alias in SELECT list",
195→                model.name, key_col
196→            ));
197→        }
198→    }
199→
200→    // --- Safety checks ---
201→
202→    // 2a: Window functions (OVER clause)
203→    if !overrides.allow_window_functions {
204→        let upper_sql = stripped_sql.to_uppercase();
205→        if upper_sql.contains("OVER(") || upper_sql.contains("OVER (") {
206→            return Err(format!(
207→                "Model '{}': window functions (OVER clause) are not compatible with incremental \
208→                 materialization — they may produce different results on partial data",
209→                model.name
210→            ));
211→        }
212→    }
213→
214→    // 2b: HAVING clause
215→    if !overrides.allow_having {
216→        let upper_sql = stripped_sql.to_uppercase();
217→        // Check for HAVING keyword at word boundary (not inside a string or identifier)
218→        if has_keyword_at_boundary(&upper_sql, "HAVING") {
219→            return Err(format!(
220→                "Model '{}': HAVING clause is not compatible with incremental materialization \
221→                 — groups may change eligibility between incremental and full runs",
222→                model.name
223→            ));
224→        }
225→    }
226→
227→    // 2c: LIMIT clause
228→    if !overrides.allow_limit {
229→        let upper_sql = stripped_sql.to_uppercase();
230→        if has_keyword_at_boundary(&upper_sql, "LIMIT") {
231→            return Err(format!(
232→                "Model '{}': LIMIT clause is not compatible with incremental materialization \
233→                 — different time ranges would produce different row subsets",
234→                model.name
235→            ));
236→        }
237→    }
238→
239→    // 2d: Subqueries in FROM
240→    if !overrides.allow_subqueries {
241→        // Check for '(' in FROM clause text (indicates subquery)
242→        if analysis.from_text.contains('(')
243→            && !analysis.from_text.contains("smelt.ref(")
244→            && !analysis.from_text.contains("smelt.source(")
245→        {
246→            return Err(format!(
247→                "Model '{}': subqueries in FROM clause are not yet supported with incremental \
248→                 materialization",
249→                model.name
250→            ));
251→        }
252→    }
253→
254→    // 2e: Non-deterministic functions
255→    if !overrides.allow_nondeterministic {
256→        let upper_sql = stripped_sql.to_uppercase();
257→        for func_name in NONDETERMINISTIC_FUNCTIONS {
258→            if has_keyword_at_boundary(&upper_sql, func_name) {
259→                return Err(format!(
260→                    "Model '{}': non-deterministic function '{}' is not compatible with \
261→                     incremental materialization — results will differ between runs",
262→                    model.name, func_name
263→                ));
264→            }
265→        }
266→    }
267→
268→    // 2f: SELECT DISTINCT
269→    if !overrides.allow_distinct {
270→        let upper_sql = stripped_sql.trim().to_uppercase();
271→        // Check for SELECT DISTINCT (not COUNT(DISTINCT ...))
272→        if upper_sql.starts_with("SELECT DISTINCT")
273→            || upper_sql.starts_with("SELECT  DISTINCT")
274→            || upper_sql.contains("\nSELECT DISTINCT")
275→        {
276→            return Err(format!(
277→                "Model '{}': SELECT DISTINCT is not compatible with incremental materialization \
278→                 — deduplication results may differ on partial data",
279→                model.name
280→            ));
281→        }
282→    }
283→
284→    Ok(Some(Opportunity {
285→        rule_name: "incremental".to_string(),
286→        model: model.name.clone(),
287→        description: format!(
288→            "Incremental materialization on partition column '{}' (source: '{}', granularity: {:?})",
289→            partition_col, event_time_column, inc_config.granularity,
290→        ),
291→        data: OpportunityData::Incremental {
292→            event_time_column: event_time_column.clone(),
293→            partition_column: partition_col.clone(),
294→            granularity: inc_config.granularity.clone(),
295→        },
296→    }))
297→}
298→
299→/// Check if a keyword appears at a word boundary in uppercase text.
300→fn has_keyword_at_boundary(upper_sql: &str, keyword: &str) -> bool {
301→    let bytes = upper_sql.as_bytes();
302→    let kw_bytes = keyword.as_bytes();
303→
304→    for i in 0..bytes.len() {
305→        if i + kw_bytes.len() > bytes.len() {
306→            break;
307→        }
308→        if &bytes[i..i + kw_bytes.len()] == kw_bytes {
309→            let before_ok = i == 0 || !bytes[i - 1].is_ascii_alphanumeric();
310→            let after_ok = i + kw_bytes.len() >= bytes.len()
311→                || !bytes[i + kw_bytes.len()].is_ascii_alphanumeric();
312→            if before_ok && after_ok {
313→                return true;
314→            }
315→        }
316→    }
317→    false
318→}
