320→/// Produce a SetIncremental transformation for a model.
321→pub fn optimize(model: &ModelInfo) -> Result<Option<Transformation>, String> {
322→    let opportunity = detect(model)?;
323→    match opportunity {
324→        None => Ok(None),
325→        Some(opp) => match &opp.data {
326→            OpportunityData::Incremental {
327→                event_time_column,
328→                partition_column,
329→                granularity,
330→            } => Ok(Some(Transformation::SetIncremental {
331→                model: model.name.clone(),
332→                event_time_column: event_time_column.clone(),
333→                partition_column: partition_column.clone(),
334→                granularity: granularity.clone(),
335→            })),
336→            _ => Ok(None),
337→        },
338→    }
339→}
