  1→use crate::config::Config;
  2→use crate::discovery::ModelFile;
  3→use crate::selector::{SelectionMethod, Selector};
  4→use crate::SourcesConfig;
  5→use anyhow::{anyhow, Result};
  6→use std::collections::{HashMap, HashSet, VecDeque};
  7→use thiserror::Error;
  8→
  9→#[derive(Debug, Error)]
 10→pub enum GraphError {
 11→    #[error("Dependency resolution failed:\n  {message}")]
 12→    DependencyError { message: String },
 13→
 14→    #[error("Circular dependency detected involving models: {models}")]
 15→    CircularDependency { models: String },
 16→}
 17→
 18→pub struct DependencyGraph {
 19→    /// model_name -> dependencies (model names it references)
 20→    dependencies: HashMap<String, Vec<String>>,
 21→    /// model_name -> ModelFile
 22→    models: HashMap<String, ModelFile>,
 23→    /// External sources (from sources.yml)
 24→    sources: HashSet<String>,
 25→}
 26→
 27→impl DependencyGraph {
 28→    pub fn build(models: Vec<ModelFile>, sources: Option<&SourcesConfig>) -> Result<Self> {
 29→        let mut dependencies = HashMap::new();
 30→        let mut models_map = HashMap::new();
 31→
 32→        // Build source set (schema.table format)
 33→        let mut source_set = HashSet::new();
 34→        if let Some(sources) = sources {
 35→            for source in &sources.sources {
 36→                for table in &source.tables {
 37→                    source_set.insert(format!("{}.{}", source.name, table.name));
 38→                }
 39→            }
 40→        }
 41→
 42→        // Build dependency map
 43→        for model in models {
 44→            let deps: Vec<String> = model.refs.iter().map(|r| r.model_name.clone()).collect();
 45→
 46→            dependencies.insert(model.name.clone(), deps);
 47→            models_map.insert(model.name.clone(), model);
 48→        }
 49→
 50→        Ok(Self {
 51→            dependencies,
 52→            models: models_map,
 53→            sources: source_set,
 54→        })
 55→    }
 56→
 57→    /// Validate all references exist (either as models or sources)
 58→    pub fn validate(&self) -> Result<()> {
 59→        let mut errors = Vec::new();
 60→
 61→        for (model_name, deps) in &self.dependencies {
 62→            for dep in deps {
 63→                // Check if dependency exists as a model or source
 64→                if !self.models.contains_key(dep) && !self.is_source(dep) {
 65→                    errors.push(format!(
 66→                        "Model '{}' references undefined model/source '{}'",
 67→                        model_name, dep
 68→                    ));
 69→                }
 70→            }
 71→        }
 72→
 73→        if !errors.is_empty() {
 74→            return Err(GraphError::DependencyError {
 75→                message: errors.join("\n  "),
 76→            }
 77→            .into());
 78→        }
 79→
 80→        Ok(())
 81→    }
 82→
 83→    fn is_source(&self, name: &str) -> bool {
 84→        // Check both plain name and schema.table format
 85→        self.sources.contains(name)
 86→            || self
 87→                .sources
 88→                .iter()
 89→                .any(|s| s.ends_with(&format!(".{}", name)))
 90→    }
 91→
 92→    /// Topological sort to determine execution order using Kahn's algorithm
 93→    pub fn execution_order(&self) -> Result<Vec<String>> {
 94→        let mut in_degree: HashMap<String, usize> = HashMap::new();
 95→        let mut dependents: HashMap<String, Vec<String>> = HashMap::new();
 96→
 97→        // Initialize in-degree for all models
 98→        for model_name in self.models.keys() {
 99→            in_degree.insert(model_name.clone(), 0);
100→            dependents.insert(model_name.clone(), Vec::new());
101→        }
102→
103→        // Count incoming edges (dependencies)
104→        for (model_name, deps) in &self.dependencies {
105→            for dep in deps {
106→                // Only count model dependencies (skip sources)
107→                if self.models.contains_key(dep) {
108→                    *in_degree.get_mut(model_name).unwrap() += 1;
109→                    dependents.get_mut(dep).unwrap().push(model_name.clone());
110→                }
111→            }
112→        }
113→
114→        // Kahn's algorithm for topological sort
115→        let mut queue: VecDeque<String> = in_degree
116→            .iter()
117→            .filter(|(_, &degree)| degree == 0)
118→            .map(|(name, _)| name.clone())
119→            .collect();
120→
121→        let mut order = Vec::new();
122→
123→        while let Some(model_name) = queue.pop_front() {
124→            order.push(model_name.clone());
125→
126→            // Reduce in-degree for dependents
127→            if let Some(deps) = dependents.get(&model_name) {
128→                for dependent in deps {
129→                    let degree = in_degree.get_mut(dependent).unwrap();
130→                    *degree -= 1;
131→
132→                    if *degree == 0 {
133→                        queue.push_back(dependent.clone());
134→                    }
135→                }
136→            }
137→        }
138→
139→        // Check for cycles
140→        if order.len() != self.models.len() {
141→            let remaining: Vec<_> = in_degree
142→                .iter()
143→                .filter(|(_, &degree)| degree > 0)
144→                .map(|(name, _)| name.as_str())
145→                .collect();
146→
147→            return Err(GraphError::CircularDependency {
148→                models: remaining.join(", "),
149→            }
150→            .into());
151→        }
152→
153→        Ok(order)
154→    }
155→
156→    /// Select models matching the given selectors, with optional upstream/downstream expansion.
157→    ///
158→    /// Returns the set of selected model names. The result is the union of all selectors.
159→    pub fn select_models(
160→        &self,
161→        selectors: &[Selector],
162→        config: &Config,
163→    ) -> Result<HashSet<String>> {
164→        let mut selected = HashSet::new();
165→        let dependents = self.build_dependents_map();
166→
167→        for selector in selectors {
168→            // Find directly matching models
169→            let direct_matches: Vec<String> = match &selector.method {
170→                SelectionMethod::ModelName(name) => {
171→                    if self.models.contains_key(name) {
172→                        vec![name.clone()]
173→                    } else {
174→                        return Err(anyhow!("Model '{}' not found", name));
175→                    }
176→                }
177→                SelectionMethod::Tag(tag) => self
178→                    .models
179→                    .iter()
180→                    .filter(|(name, model)| {
181→                        let tags =
182→                            config.get_tags(name, model.metadata.as_ref().map(|b| b.as_ref()));
183→                        tags.contains(tag)
184→                    })
185→                    .map(|(name, _)| name.clone())
186→                    .collect(),
187→            };
188→
189→            for model_name in &direct_matches {
190→                selected.insert(model_name.clone());
191→            }
192→
193→            // Expand upstream
194→            if selector.include_upstream {
195→                for model_name in &direct_matches {
196→                    self.collect_upstream(model_name, &mut selected);
197→                }
198→            }
199→
200→            // Expand downstream
201→            if selector.include_downstream {
202→                for model_name in &direct_matches {
203→                    self.collect_downstream(model_name, &dependents, &mut selected);
204→                }
205→            }
206→        }
207→
208→        Ok(selected)
209→    }
210→
211→    /// Collect all upstream dependencies recursively.
212→    fn collect_upstream(&self, model_name: &str, result: &mut HashSet<String>) {
213→        if let Some(deps) = self.dependencies.get(model_name) {
214→            for dep in deps {
215→                if self.models.contains_key(dep) && result.insert(dep.clone()) {
216→                    self.collect_upstream(dep, result);
217→                }
218→            }
219→        }
220→    }
221→
222→    /// Build a reverse map: model_name -> models that depend on it.
223→    fn build_dependents_map(&self) -> HashMap<String, Vec<String>> {
224→        let mut dependents: HashMap<String, Vec<String>> = HashMap::new();
225→        for (model_name, deps) in &self.dependencies {
226→            for dep in deps {
227→                if self.models.contains_key(dep) {
228→                    dependents
229→                        .entry(dep.clone())
230→                        .or_default()
231→                        .push(model_name.clone());
232→                }
233→            }
234→        }
235→        dependents
236→    }
237→
238→    /// Collect all downstream dependents recursively.
239→    fn collect_downstream(
240→        &self,
241→        model_name: &str,
242→        dependents: &HashMap<String, Vec<String>>,
243→        result: &mut HashSet<String>,
244→    ) {
245→        if let Some(deps) = dependents.get(model_name) {
246→            for dep in deps {
247→                if result.insert(dep.clone()) {
248→                    self.collect_downstream(dep, dependents, result);
249→                }
250→            }
251→        }
252→    }
253→
254→    /// Filter execution order to only include selected models.
255→    pub fn filtered_execution_order(&self, selected: &HashSet<String>) -> Result<Vec<String>> {
256→        let full_order = self.execution_order()?;
257→        Ok(full_order
258→            .into_iter()
259→            .filter(|name| selected.contains(name))
260→            .collect())
261→    }
262→
263→    pub fn get_model(&self, name: &str) -> Result<&ModelFile> {
264→        self.models
265→            .get(name)
266→            .ok_or_else(|| anyhow!("Model not found: {}", name))
267→    }
268→
269→    pub fn model_count(&self) -> usize {
270→        self.models.len()
271→    }
272→
273→    pub fn iter_models(&self) -> impl Iterator<Item = (&str, &ModelFile)> {
274→        self.models.iter().map(|(k, v)| (k.as_str(), v))
275→    }
276→
277→    pub fn iter_dependencies(&self) -> impl Iterator<Item = (&str, &[String])> {
278→        self.dependencies
279→            .iter()
280→            .map(|(k, v)| (k.as_str(), v.as_slice()))
281→    }
282→
283→    pub fn iter_sources(&self) -> impl Iterator<Item = &str> {
284→        self.sources.iter().map(|s| s.as_str())
285→    }
286→}
