for model in &models {
    if !model.parse_errors.is_empty() {
        eprintln!("\nWarning: Parse errors in {}:", model.name);
        for error in &model.parse_errors {
            eprintln!("  - {} at {:?}", error.message, error.range);
        }
    }
}

// 4. Build dependency graph
