                args.show_results,
            )
            .await
            .with_context(|| format!("Failed to execute model: {}", model_name))?
        }
        ModelExecution::CubeSplit { steps } => {
            // Cube split only (full refresh)
            println!("\n▶ Running model: {} (cube split)", model_name);

